import { Box, Flex, Text } from "@chakra-ui/react";
import React, { forwardRef } from "react";
import { Icon } from "../../../Icon";
import { CommentXMark } from "../../../Icon/icons";
import type { ConversationEvent, ConversationEventAction } from "../../../types";
import { ConversationEventActionButton } from "../../ConversationEventActionButton";
import { useConversationLogSx } from "../useConversationLogSx";

interface UserInputSuppressedEventProps {
  event: ConversationEvent;
  isSelected: boolean;
  conversationEventActions?: ConversationEventAction[];
  onClick?: React.MouseEventHandler<HTMLDivElement>;
  onKeyDown?: (event: React.KeyboardEvent<HTMLDivElement>) => void;
}

export const UserInputSuppressedEvent = forwardRef<
  HTMLDivElement | null,
  UserInputSuppressedEventProps
>((props, ref) => {
  const {
    event,
    isSelected = false,
    conversationEventActions,
    onClick,
    onKeyDown,
    ...otherProps
  } = props;
  const { hoverableContainerSx, baseMessageSx, iconSx } = useConversationLogSx(isSelected);
  const [isHovered, setIsHovered] = React.useState(false);

  return (
    <Flex
      css={hoverableContainerSx}
      ref={ref}
      tabIndex={0}
      role="button"
      position="relative"
      cursor="pointer"
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      onClick={onClick}
      onKeyDown={onKeyDown}
      {...otherProps}
    >
      {isHovered && (
        <ConversationEventActionButton event={event} actions={conversationEventActions} />
      )}
      <Box css={baseMessageSx}>
        <Icon icon={CommentXMark} style={iconSx} />
        <Text textStyle="xs" variant="muted" lineClamp={2} wordBreak="break-all">
          User input suppressed
        </Text>
      </Box>
    </Flex>
  );
});

UserInputSuppressedEvent.displayName = "UserInputSuppressedEvent";
